tags.gen_ai.tool.definitions:
[
  {
    "type": "function",
    "name": "list_clusters",
    "description": "Listet die Feature-Cluster (clusterId, label, core-/crossCutting-Anzahl).",
    "parameters": {
      "type": "object",
      "properties": {}
    }
  },
  {
    "type": "function",
    "name": "get_feature_context",
    "description": "Liefert fuer EINEN Cluster den vollen Kontext: core- und crossCutting-Requirements mit Titel und Text.",
    "parameters": {
      "type": "object",
      "properties": {
        "clusterId": {
          "type": "string"
        }
      },
      "required": [
        "clusterId"
      ]
    }
  },
  {
    "type": "function",
    "name": "get_requirement",
    "description": "Liest ein einzelnes Requirement vollstaendig.",
    "parameters": {
      "type": "object",
      "properties": {
        "requirementId": {
          "type": "string"
        }
      },
      "required": [
        "requirementId"
      ]
    }
  },
  {
    "type": "function",
    "name": "check_pbis",
    "description": "Prueft die PBIs deterministisch (Coverage der Cluster-Cores, keine stille Luecke). Vor dem Speichern nutzen.",
    "parameters": {
      "type": "object",
      "properties": {
        "items": {
          "type": "array",
          "items": {
            "type": "object",
            "properties": {
              "pbiId": {
                "type": "string"
              },
              "identityKey": {
                "type": "string"
              },
              "version": {
